    )
    .unwrap();
    assert_eq!(proofs.len(), 7);
    let mut paths = std::collections::BTreeSet::new();
    let mut created = std::collections::BTreeSet::new();
    let mut merger = String::new();
    for proof in &proofs {
        let path = proof["path"].as_str().unwrap();
