                let hook = "        #[cfg(test)]\n        tests::record_core_attempt(\n            fallback_mode,\n            resolve_builder_bytes,\n            consumed,\n            overflowed,\n            &refusal,\n            &site,\n            &core.as_ref().err(),\n        );\n";
